<script setup>
import {computed,nextTick,ref,watch} from 'vue'
import {useData} from 'vitepress'
import chineseChapters from '../../data/tour.json'
import englishChapters from '../../data/tour-en.json'
import chineseMedia from '../../data/tour-media.json'
import englishMedia from '../../data/tour-en-media.json'
const props=defineProps({compact:Boolean})
const {frontmatter}=useData(),en=computed(()=>frontmatter.value.locale==='en'),player=ref(null),started=ref(false),playError=ref(false),pendingTime=ref(0)
const chapters=computed(()=>en.value?englishChapters:chineseChapters),media=computed(()=>en.value?englishMedia:chineseMedia)
const videoFile=computed(()=>en.value?'/media/rivomesh-tour-en.mp4':'/media/rivomesh-tour.mp4'),poster=computed(()=>en.value?'/media/tour-poster-en.png':'/media/tour-poster.png')
const englishTrack=computed(()=>en.value?'/media/tour-en.en.vtt':'/media/tour.en.vtt'),chineseTrack=computed(()=>en.value?'/media/tour-en.zh-CN.vtt':'/media/tour.zh-CN.vtt')
const asset=path=>`${path}?v=${media.value.revision}`
watch(en,()=>{player.value?.pause();started.value=false;pendingTime.value=0;playError.value=false})
const stamp=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`
const duration=computed(()=>chapters.value.length?chapters.value.at(-1).time+chapters.value.at(-1).duration:0)
async function play(){try{await player.value?.play();playError.value=false}catch{playError.value=true}}
function ready(){for(const track of Array.from(player.value.textTracks||[]))track.mode=track.language===(en.value?'en':'zh-CN')?'showing':'disabled';if(pendingTime.value)player.value.currentTime=pendingTime.value;play()}
async function seek(time=0){pendingTime.value=time;if(!started.value){started.value=true;await nextTick();player.value?.load()}else if(player.value){if(player.value.readyState>=1){player.value.currentTime=time;play()}}}
</script>
<template><div class="product-tour" :class="{compact}"><div class="tour-heading"><div><strong>{{en?'A short product walkthrough':'用一个短片了解产品'}}</strong><span>{{stamp(duration)}} · {{en?'English narration · Bilingual subtitles':'中文讲解 · 双语字幕'}}</span></div><a :href="en?'/en/tour.html':'/tour.html'" v-if="compact">{{en?'Full tour':'完整导览'}} →</a></div><div class="video-frame"><button v-if="!started" class="video-poster" @click="seek(0)" :aria-label="en?'Load and play the RivoMesh walkthrough':'加载并播放 RivoMesh 产品讲解'"><img :src="poster" :alt="en?'RivoMesh narrated walkthrough cover':'RivoMesh 产品讲解封面'" width="1280" height="720" loading="lazy" decoding="async"><span class="video-start"><svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor" aria-hidden="true"><path d="m8 4 12 8-12 8V4Z"/></svg>{{en?'Play walkthrough':'播放产品讲解'}}</span></button><video v-else ref="player" class="product-video" controls playsinline preload="none" width="1280" height="720" :poster="poster" :aria-label="en?'RivoMesh: AI-generated English narration with English subtitles':'RivoMesh AI 合成中文产品讲解，中英文字幕'" @loadedmetadata="ready"><source :src="asset(videoFile)" type="video/mp4"><track kind="subtitles" :src="asset(englishTrack)" label="English" srclang="en" :default="en"><track kind="captions" :src="asset(chineseTrack)" label="简体中文" srclang="zh-CN" :default="!en">{{en?'Download the video or read the transcript below.':'请下载视频或阅读下方文字稿。'}}</video></div><p v-if="playError" class="video-feedback" role="status">{{en?'Use the video controls to start playback.':'请使用视频控制按钮开始播放。'}}</p><div class="video-chapters" :aria-label="en?'Video chapters':'讲解章节'"><button v-for="chapter in chapters" :key="chapter.time" @click="seek(chapter.time)"><span>{{stamp(chapter.time)}}</span>{{chapter.title}}</button></div><div class="video-resources"><span>{{en?'AI narration by OpenAI · Video loads on play.':'旁白由 OpenAI 合成 · 点击播放后加载视频。'}}</span><nav :aria-label="en?'Video files and transcript':'视频文件与文字稿'"><a :href="asset(videoFile)" download>{{en?'Download video':'下载视频'}}</a><a :href="en?'/media/transcript.en.txt':'/media/transcript.txt'">{{en?'Transcript':'文字稿'}}</a><a :href="asset(en?englishTrack:chineseTrack)">{{en?'Subtitles':'字幕'}}</a></nav></div></div></template>
<style scoped>
.product-tour{margin-top:28px}.tour-heading{display:flex;align-items:baseline;justify-content:space-between;gap:15px;margin-bottom:15px}.tour-heading>div{display:flex;align-items:baseline;gap:16px;flex-wrap:wrap}.tour-heading strong{font-size:15px;font-weight:550}.tour-heading span{font-size:11px;color:var(--muted)}.tour-heading>a{font-size:12px;color:var(--blue);white-space:nowrap}.video-frame{border:1px solid var(--line);border-radius:var(--radius-panel);overflow:hidden;background:var(--surface);aspect-ratio:16/9}.video-poster{position:relative;display:block;padding:0;width:100%;height:100%;text-align:left}.video-poster>img{display:block;width:100%;height:100%;object-fit:contain}.video-start{display:flex;align-items:center;gap:10px;position:absolute;left:24px;bottom:24px;color:#fff;background:#172a45eb;border:1px solid #ffffff50;border-radius:var(--radius-control);padding:12px 18px;font-size:13px;min-height:44px;transition:background var(--motion-fast) var(--ease-ui)}.video-poster:hover .video-start{background:#2859a6}.video-start svg{flex:none}.product-video{display:block;width:100%;height:auto;aspect-ratio:16/9;border:0;border-radius:0;max-height:75dvh}.video-chapters{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:0;margin-top:0;border-bottom:1px solid var(--line)}.video-chapters button{min-width:0;text-align:left;padding:15px 12px;font-size:11px;line-height:1.75;border:0;border-right:1px solid var(--line);border-radius:0;min-height:60px;background:none}.video-chapters button:first-child{padding-left:0}.video-chapters button:last-child{border-right:0}.video-chapters button span{display:block;font:10px/1.8 monospace;color:var(--blue);margin-bottom:3px}.video-chapters button:hover{background:var(--surface)}.video-resources{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:8px 20px;font-size:10px;color:var(--muted);margin-top:14px;line-height:1.8}.video-resources nav{display:flex;gap:18px}.video-resources a{color:var(--blue);padding:6px 0}.video-feedback{font-size:12px;color:var(--muted);margin-top:10px!important}.compact{padding-top:30px;margin-top:32px;border-top:1px solid var(--line)}@media(max-width:760px){.video-chapters{grid-template-columns:repeat(3,minmax(0,1fr))}.video-chapters button{padding:11px;border-bottom:1px solid var(--line);border-right:0}.video-chapters button:first-child{padding-left:11px}.video-start{left:15px;bottom:15px;padding:10px 13px;font-size:12px}}@media(max-width:400px){.tour-heading>div{gap:5px}.tour-heading strong{font-size:13px}.tour-heading span{font-size:10px}.video-start{font-size:11px;gap:7px;padding:9px 12px}.video-chapters{grid-template-columns:1fr 1fr}.video-chapters button{font-size:10px;min-height:52px}.video-resources{font-size:10px}.video-resources nav{gap:16px}.tour-heading>a{font-size:11px}}
</style>
